css:
@import url("https://fonts.googleapis.com/css2?family=Poiret+One&family=Questrial&display=swap");
:root{--ms:#3B4A3F;--ms2:#2C382F;--pl:#E8D5CC;--pl2:#F4EAE5;--ch:#262626;--gr:#5E5A57;--ln:#E2D8D2;--h:"Poiret One",Georgia,serif;--b:"Questrial",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.7;color:var(--ch);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:400;margin:0;line-height:1.08}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--pl);padding:8px;z-index:99}
:focus-visible{outline:2px solid var(--ms);outline-offset:3px}
.nav{display:flex;justify-content:space-between;align-items:center;height:86px;position:relative}.logo{font-family:var(--h);font-size:30px;text-decoration:none;font-weight:700}
.menu{display:flex;gap:30px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;border-bottom:1px solid transparent}.menu a:hover{border-color:var(--ch)}
.burger{display:none;background:none;border:1px solid var(--ch);width:44px;height:40px;font-size:20px;cursor:pointer}
.hero{display:grid;grid-template-columns:.9fr 1.1fr;min-height:620px}.hero .t{background:var(--pl);padding:70px 50px 70px max(24px,calc((100vw - 1200px)/2 + 24px));display:flex;flex-direction:column;justify-content:flex-end}
.hero h1{font-size:clamp(52px,6.6vw,104px);font-weight:700;color:var(--ms2)}.hero p{max-width:26em;margin:24px 0 30px;color:var(--gr);font-size:18px}
.hero .ph{position:relative;overflow:hidden}.hero .ph img{width:100%;height:100%;object-fit:cover}
.arch{position:absolute;left:30px;bottom:30px;background:#fff;border-radius:160px 160px 0 0;padding:40px 26px 22px;max-width:240px;text-align:center;font-size:15px}.arch b{display:block;font-family:var(--h);font-size:40px;font-weight:700;color:var(--ms)}
.btn{display:inline-block;background:var(--ms);color:#fff;text-decoration:none;font:400 16px var(--b);padding:15px 28px;border:0;cursor:pointer;letter-spacing:.04em}.btn.l{background:transparent;color:var(--ms);box-shadow:inset 0 0 0 1px var(--ms)}
.row{display:flex;flex-wrap:wrap;gap:12px}
section{padding:90px 0}.sh{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:34px}.sh h2{font-size:clamp(40px,5vw,66px);font-weight:700}.sh p{color:var(--gr);margin:6px 0 0;max-width:30em}
.flt{display:flex;flex-wrap:wrap;gap:4px 18px}.flt button{font:400 16px var(--b);background:none;border:0;border-bottom:1px solid transparent;padding:4px 0;cursor:pointer;color:var(--gr)}.flt button[aria-pressed=true]{color:var(--ch);border-color:var(--ch)}
.pf{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px;align-items:start}
.pj{margin:0}.pj img{width:100%;aspect-ratio:4/5;object-fit:cover}.pj:nth-child(3n+2){margin-top:60px}.pj figcaption{padding-top:12px;display:flex;justify-content:space-between;gap:10px}.pj b{font-family:var(--h);font-size:24px;font-weight:700}.pj span{color:var(--gr);font-size:15px}
.quiz{background:var(--pl2)}.qg{display:grid;grid-template-columns:1.2fr .8fr;gap:40px;align-items:start}.qg>div{min-width:0}
.q{margin-bottom:26px}.q p{font-family:var(--h);font-size:28px;font-weight:700;margin:0 0 12px}
.cs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.cs label{cursor:pointer;position:relative}.cs input{position:absolute;opacity:0;width:1px;height:1px;left:0;top:0}
.cs .sw{display:block;height:90px;border:3px solid transparent}.cs span.t{display:block;font-size:15px;padding-top:6px}.cs input:checked+.sw{border-color:var(--ch);box-shadow:0 0 0 3px #fff inset}.cs input:focus-visible+.sw{outline:2px solid var(--ms);outline-offset:3px}
.res{background:var(--ms);color:#fff;padding:32px;position:sticky;top:20px}.res small{color:#C9D3CB}.res h3{font-size:44px;font-weight:700;margin:8px 0 12px}.res p{color:#E1E7E2}.pal{display:flex;margin:18px 0 22px}.pal i{flex:1;height:50px}
.res .btn{background:var(--pl);color:var(--ch)}
.svc{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;border-top:1px solid var(--ln)}.sv{padding:30px 30px 30px 0;border-right:1px solid var(--ln);margin-right:30px}.sv:last-child{border:0}
.sv h3{font-size:32px;font-weight:700}.sv .pr{color:var(--ms);font-size:18px;margin:6px 0 12px}.sv p{color:var(--gr);margin:0}
.con{background:var(--ms2);color:#fff}.cg{display:grid;grid-template-columns:1fr 1fr;gap:50px}.con .sh p{color:#C9D3CB}
form{display:grid;gap:4px}.fr{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fr>div{min-width:0}
.con label{display:block;font-size:15px;margin-bottom:6px;color:#DDE3DE}.con input,.con select,.con textarea{width:100%;font:16px var(--b);padding:12px 0;border:0;border-bottom:1px solid #7C8B80;background:transparent;color:#fff;margin-bottom:16px}.con select option{color:var(--ch)}
.con .btn{background:var(--pl);color:var(--ch);justify-self:start}.msg{visibility:hidden;color:var(--pl);margin:10px 0 0}.msg.on{visibility:visible}
footer{padding:28px 0;font-size:15px;color:var(--gr)}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hero,.qg,.cg{grid-template-columns:1fr}.hero .t{padding:50px 24px}.hero .ph{height:420px}.pf{grid-template-columns:1fr 1fr}.pj:nth-child(3n+2){margin-top:0}.pj:nth-child(2n){margin-top:40px}.svc{grid-template-columns:1fr}.sv{border-right:0;border-bottom:1px solid var(--ln);margin-right:0}.res{position:static}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:86px;left:0;right:0;background:#fff;flex-direction:column;padding:18px 24px;z-index:30;border-bottom:1px solid var(--ln)}.menu.open{display:flex}.pf{grid-template-columns:1fr}.pj:nth-child(2n){margin-top:0}.fr{grid-template-columns:1fr}.cs .sw{height:64px}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);const U=i=>`https://images.unsplash.com/photo-${i}?w=700&q=75&auto=format&fit=crop`;
const P=[["Alder Street house","Living","1616486338812-3dadae4b4ace","Bright living room with a round coffee table and rattan details"],["Hawthorne flat","Workspace","1586023492125-27b2c045efd7","Yellow armchair and lamp in a white room"],["Laurelhurst kitchen","Kitchen","1556912173-3bb406ef7e77","White kitchen with glass cabinets and a range cooker"],["Sellwood bungalow","Bedroom","1505693416388-ac5ce068fe85","Bedroom with tufted headboard and bedside lamps"],["Pearl loft","Living","1560448204-e02f11c3d0e2","Open living room with big windows and cream sofas"],["Reading corner","Workspace","1502672260266-1c1ef2d93688","Reading nook with plants and a lounge chair"]];
function pf(r){$('pf').innerHTML=P.filter(p=>r==='all'||p[1]===r).map(p=>`<figure class="pj"><img src="${U(p[2])}" alt="${p[3]}" width="700" height="875" loading="lazy"><figcaption><b>${p[0]}</b><span>${p[1]}</span></figcaption></figure>`).join('')}
$('flt').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('flt').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));pf(b.dataset.r)};pf('all');
const S={w:["Warm minimal","Natural wood, soft textures and very little clutter. Rooms that feel calm the moment you walk in.",["#E9DCC9","#C9A987","#7A5C45","#F6F1EA"]],s:["Soft modern","Clean shapes, muted greens and lots of plants. Fresh and easy to live with.",["#DDE3E0","#A8B8B2","#50605B","#FFFFFF"]],c:["Collected classic","Deep colours, vintage finds and pattern. Every piece has a story.",["#1F3A5F","#B2463A","#E4B64B","#EFE6D8"]]};
function res(){const v=['a','b','c'].map(n=>document.querySelector(`input[name=${n}]:checked`).value);const c={};v.forEach(x=>c[x]=(c[x]||0)+1);const k=Object.keys(c).sort((a,b)=>c[b]-c[a])[0];const s=S[c[k]>1?k:v[0]];
$('sn').textContent=s[0];$('sd').textContent=s[1];$('sp').innerHTML=s[2].map(x=>`<i style="background:${x}"></i>`).join('');$('cst').value=s[0]}
$('qz').addEventListener('change',res);res();
$('cf').onsubmit=e=>{e.preventDefault();$('msg').textContent=`Thank you, ${$('cn').value}. We'll be in touch within two working days.`;$('msg').classList.add('on')};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
